    @Test
    void shouldConvertAppOrderAmountsFromCentToYuanInBaseQuery() throws IOException {
        String xml = new ClassPathResource("mapper/DwsAppOrderD.xml")
                .getContentAsString(StandardCharsets.UTF_8);

        assertThat(xml).contains("CAST(IFNULL(SUM(o.order_pay_amt), 0) / 100.0 AS DECIMAL(20, 2)) AS rechargeAmount");
        assertThat(xml).contains("CAST(IFNULL(SUM(o.new_order_pay_amt), 0) / 100.0 AS DECIMAL(20, 2)) AS newRechargeAmount");
        assertThat(xml).contains("CAST(IFNULL(SUM(o.old_order_pay_amt), 0) / 100.0 AS DECIMAL(20, 2)) AS oldRechargeAmount");
    }

    @Test
    void shouldUnionPayUserBitmapsInsteadOfSummingPerDimCounts() throws IOException {
        String xml = new ClassPathResource("mapper/DwsAppOrderD.xml")
                .getContentAsString(StandardCharsets.UTF_8);

        assertThat(xml).contains("FROM dws.dws_app_order_d_h o");
        assertThat(xml).contains("BITMAP_UNION_COUNT(BITMAP_UNION(o.order_pay_users))");
        assertThat(xml).contains("BITMAP_UNION_COUNT(BITMAP_UNION(o.new_order_pay_users))");
        assertThat(xml).contains("BITMAP_UNION_COUNT(BITMAP_UNION(o.old_order_pay_users))");
        assertThat(xml).doesNotContain("IFNULL(SUM(o.order_pay_users), 0) AS rechargeUsers");
    }
}

