# 从 transcript 抽早上前后 assistant 结论句
python3 << 'PY'
import json
path="/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts/f6e059e2-86bd-4592-acdf-940b0f2e1547/f6e059e2-86bd-4592-acdf-940b0f2e1547.jsonl"
rows=[]
with open(path) as f:
    for line in f:
        try: o=json.loads(line)
        except: continue
        role=o.get("role")
        msg=o.get("message") or {}
        content=msg.get("content") if isinstance(msg,dict) else None
        texts=[]
        if isinstance(content,list):
            for c in content:
                if isinstance(c,dict) and c.get("type")=="text":
                    texts.append(c.get("text") or "")
        elif isinstance(content,str):
            texts.append(content)
        text="\n".join(texts)
        if not text.strip():
            continue
        # keep user queries and short assistant verdicts around Sep 17-18
        if role=="user" and ("核对" in text or "差了" in text or "没问题" in text or "生产" in text or "提交" in text or "还有什么" in text or "早上" in text or "两组" in text or "原因" in text):
            ts=""
            if "<timestamp>" in text:
                ts=text.split("<timestamp>")[1].split("</timestamp>")[0][:25]
            rows.append(("U", ts, text.replace("\n"," ")[:180]))
        if role=="assistant" and any(k in text for k in ["没问题","对齐","结论","prod","生产","test","126597","64401","根因","漏了","未 commit"]):
            # first 200 chars of verdict-like replies
            if len(text)>80 and ("##" in text[:20] or "结论" in text[:80] or "根因" in text or "对齐" in text[:200] or "prod" in text[:300] or "未" in text[:200]):
                rows.append(("A", "", text.replace("\n"," ")[:220]))
print("n", len(rows))
for r in rows[-40:]:
    print(r[0], r[1], r[2])
    print("---")
PY
